import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpiryTest {

    private final Instant now = Instant.parse("2026-10-31T10:00:00Z");
    private final Clock clock = Clock.fixed(now, ZoneOffset.UTC);

    @Test
    void cancelsOnlyPlacedOrdersOlderThan30Days() {
        OrderRepository repository = new OrderRepository();
        OrderService service = new OrderService(repository, clock);

        Order old = new Order("old", "c", Money.pln(100), now.minusSeconds(31L * 86_400));
        Order exactly30 = new Order("edge", "c", Money.pln(100), now.minus(java.time.Duration.ofDays(30)));
        Order recent = new Order("recent", "c", Money.pln(100), now.minusSeconds(29L * 86_400));
        Order oldConfirmed = new Order("confirmed", "c", Money.pln(100), now.minusSeconds(40L * 86_400));
        oldConfirmed.changeStatus("CONFIRMED");
        repository.save(old);
        repository.save(exactly30);
        repository.save(recent);
        repository.save(oldConfirmed);

        int cancelled = service.expireStale();

        assertEquals(1, cancelled);
        assertEquals("CANCELLED", old.status());
        assertEquals("PLACED", exactly30.status());
        assertEquals("PLACED", recent.status());
        assertEquals("CONFIRMED", oldConfirmed.status());
    }

    @Test
    void returnsZeroWhenNothingIsStale() {
        OrderRepository repository = new OrderRepository();
        OrderService service = new OrderService(repository, clock);

        assertEquals(0, service.expireStale());
    }
}
}
